function crearDoble() {
  const raiz = {};
  raiz.siguiente = raiz;
  raiz.anterior = raiz;
  return raiz;
}

function ponerAntes(destino, valor) {
  const nodo = { valor, anterior: destino.anterior, siguiente: destino };
  nodo.anterior.siguiente = nodo;
  destino.anterior = nodo;
  return nodo;
}

function sacarDoble(nodo) {
  nodo.anterior.siguiente = nodo.siguiente;
  nodo.siguiente.anterior = nodo.anterior;
}

function crearLRU(capacidad) {
  const raiz = crearDoble();
  const indice = new Map();
  function promover(nodo) {
    sacarDoble(nodo);
    indice.set(nodo.valor.clave, ponerAntes(raiz, nodo.valor));
  }
  return {
    leer(clave) {
      const nodo = indice.get(clave);
      if (!nodo) return { acierto: false, valor: null };
      promover(nodo);
      return { acierto: true, valor: nodo.valor.valor };
    },
    guardar(clave, valor) {
      if (capacidad === 0) return;
      const nodo = indice.get(clave);
      if (nodo) {
        nodo.valor.valor = valor;
        promover(nodo);
        return;
      }
      if (indice.size === capacidad) {
        const expulsado = raiz.siguiente;
        sacarDoble(expulsado);
        indice.delete(expulsado.valor.clave);
      }
      indice.set(clave, ponerAntes(raiz, { clave, valor }));
    },
    orden() {
      const claves = [];
      for (let nodo = raiz.siguiente; nodo !== raiz; nodo = nodo.siguiente)
        claves.push(nodo.valor.clave);
      return claves;
    },
  };
}

function tablaPrefijos(patron) {
  const pi = Array(patron.length).fill(0);
  let largo = 0;
  for (let i = 1; i < patron.length; i++) {
    while (largo && patron[i] !== patron[largo]) largo = pi[largo - 1];
    if (patron[i] === patron[largo]) largo++;
    pi[i] = largo;
  }
  return pi;
}

function buscarKMP(texto, patron) {
  if (!patron.length)
    return Array.from({ length: texto.length + 1 }, (_, i) => i);
  const pi = tablaPrefijos(patron);
  const indices = [];
  let largo = 0;
  for (let i = 0; i < texto.length; i++) {
    while (largo && texto[i] !== patron[largo]) largo = pi[largo - 1];
    if (texto[i] === patron[largo]) largo++;
    if (largo === patron.length) {
      indices.push(i - patron.length + 1);
      largo = pi[largo - 1];
    }
  }
  return indices;
}

function canonizarNombre(texto) {
  return texto.trim().toLowerCase().normalize("NFC");
}

function indiceDeNombres(estaciones) {
  const porNombre = new Map();
  for (const [codigo, nombre] of estaciones) {
    const clave = canonizarNombre(nombre);
    if (!porNombre.has(clave)) porNombre.set(clave, []);
    porNombre.get(clave).push(codigo);
  }
  return porNombre;
}

function catalogoTesla(estaciones, acciones, capacidad) {
  const nombres = indiceDeNombres(estaciones);
  const cache = crearLRU(capacidad);
  const historia = [];
  const respuestas = [];
  for (const [modo, consulta] of acciones) {
    if (modo === "deshacer") {
      respuestas.push(historia.pop() ?? null);
      continue;
    }
    const clave = canonizarNombre(consulta);
    const claveCache = JSON.stringify([modo, clave]);
    const previa = cache.leer(claveCache);
    let codigos = previa.valor;
    if (!previa.acierto) {
      if (clave === "") codigos = [];
      else if (modo === "exacta") codigos = nombres.get(clave) ?? [];
      else {
        const aceptados = new Set();
        for (const nombre of nombres.keys()) {
          if (buscarKMP(nombre, clave).length) aceptados.add(nombre);
        }
        codigos = estaciones
          .filter(([, nombre]) => aceptados.has(canonizarNombre(nombre)))
          .map(([codigo]) => codigo);
      }
      cache.guardar(claveCache, codigos);
    }
    historia.push({ modo, clave, codigos });
    respuestas.push({ acierto: previa.acierto, codigos });
  }
  return { respuestas, historia };
}

function limiteHorario(datos, hora, despues = false) {
  let inicio = 0;
  let fin = datos.length;
  while (inicio < fin) {
    const medio = inicio + Math.floor((fin - inicio) / 2);
    const minuto = datos[medio];
    if (minuto < hora || (despues && minuto === hora)) inicio = medio + 1;
    else fin = medio;
  }
  return inicio;
}

function aparicionesHorario(datos, hora) {
  const primera = limiteHorario(datos, hora);
  const fin = limiteHorario(datos, hora, true);
  return primera === fin ? null : [primera, fin - 1];
}

function consultarHorario(datos, hora) {
  const apariciones = aparicionesHorario(datos, hora);
  const siguiente = datos[limiteHorario(datos, hora)] ?? null;
  return { apariciones, siguiente };
}

function primerVerdadero(inicio, fin, cumple) {
  while (inicio < fin) {
    const medio = inicio + Math.floor((fin - inicio) / 2);
    if (cumple(medio)) fin = medio;
    else inicio = medio + 1;
  }
  return inicio;
}
function inicioAutorizado(estados) {
  return primerVerdadero(0, estados.length, (i) => estados[i]);
}

function viajesPara(cargas, capacidad) {
  let viajes = 0;
  let ocupado = 0;
  for (const peso of cargas) {
    if (peso > capacidad) return null;
    if (!viajes || ocupado + peso > capacidad) {
      viajes++;
      ocupado = 0;
    }
    ocupado += peso;
  }
  return viajes;
}

function capacidadMinima(cargas, maximoViajes) {
  let mayor = 0;
  let suma = 0;
  for (const peso of cargas) {
    mayor = Math.max(mayor, peso);
    suma += peso;
  }
  return primerVerdadero(mayor, suma, (capacidad) => {
    const viajes = viajesPara(cargas, capacidad);
    return viajes !== null && viajes <= maximoViajes;
  });
}

function porInsercion(registros) {
  const salida = registros.slice();
  for (let i = 1; i < salida.length; i++) {
    const nuevo = salida[i];
    let hueco = i;
    while (hueco > 0 && salida[hueco - 1][0] > nuevo[0]) {
      salida[hueco] = salida[hueco - 1];
      hueco--;
    }
    salida[hueco] = nuevo;
  }
  return salida;
}

function porSeleccion(registros) {
  const salida = registros.slice();
  for (let i = 0; i < salida.length; i++) {
    let menor = i;
    for (let j = i + 1; j < salida.length; j++) {
      if (salida[j][0] < salida[menor][0]) menor = j;
    }
    [salida[i], salida[menor]] = [salida[menor], salida[i]];
  }
  return salida;
}
function porBurbuja(registros) {
  const salida = registros.slice();
  for (let fin = salida.length - 1; fin > 0; fin--) {
    let huboCambio = false;
    for (let i = 0; i < fin; i++) {
      if (salida[i][0] > salida[i + 1][0]) {
        [salida[i], salida[i + 1]] = [salida[i + 1], salida[i]];
        huboCambio = true;
      }
    }
    if (!huboCambio) break;
  }
  return salida;
}
function contrastarCuadraticos(registros) {
  return { seleccion: porSeleccion(registros), burbuja: porBurbuja(registros) };
}

function prepararListado(registros) {
  const insercion = porInsercion(registros);
  const { seleccion, burbuja } = contrastarCuadraticos(registros);
  const empatesConservados = insercion.every(
    (registro, i) => registro[1] === burbuja[i][1],
  );
  return { insercion, seleccion, burbuja, empatesConservados };
}

function mezclarHorarios(a, b) {
  const salida = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i][0] <= b[j][0]) salida.push(a[i++]);
    else salida.push(b[j++]);
  }
  for (; i < a.length; i++) salida.push(a[i]);
  for (; j < b.length; j++) salida.push(b[j]);
  return salida;
}

function ordenarMezcla(registros) {
  if (registros.length < 2) return registros.slice();
  const medio = Math.floor(registros.length / 2);
  const izquierda = ordenarMezcla(registros.slice(0, medio));
  const derecha = ordenarMezcla(registros.slice(medio));
  return mezclarHorarios(izquierda, derecha);
}

function consultaOrdenada(registros, minuto) {
  const horario = ordenarMezcla(registros);
  const consulta = consultarHorario(
    horario.map((registro) => registro[0]),
    minuto,
  );
  return { horario, consulta };
}

function partirTres(datos, inicio, fin, pivote) {
  let menor = inicio;
  let i = inicio;
  let mayor = fin;
  while (i < mayor) {
    if (datos[i] < pivote) {
      [datos[menor], datos[i]] = [datos[i], datos[menor]];
      menor++;
      i++;
    } else if (datos[i] > pivote) {
      mayor--;
      [datos[i], datos[mayor]] = [datos[mayor], datos[i]];
    } else i++;
  }
  return [menor, mayor];
}
function separarClaves(datos, pivote) {
  const copia = datos.slice();
  const [menor, mayor] = partirTres(copia, 0, copia.length, pivote);
  return [copia.slice(0, menor), copia.slice(menor, mayor), copia.slice(mayor)];
}

function ordenarRapido(datos, fraccion) {
  const copia = datos.slice();
  const pendientes = [[0, copia.length]];
  while (pendientes.length) {
    const [inicio, fin] = pendientes.pop();
    if (fin - inicio < 2) continue;
    const muestra = fraccion === undefined ? Math.random() : fraccion;
    const pivote = copia[inicio + Math.floor(muestra * (fin - inicio))];
    const [menor, mayor] = partirTres(copia, inicio, fin, pivote);
    pendientes.push([inicio, menor], [mayor, fin]);
  }
  return copia;
}

function brechasHorarias(datos, fraccion) {
  const orden = ordenarRapido(datos, fraccion);
  const brechas = orden.slice(1).map((minuto, i) => minuto - orden[i]);
  return { orden, brechas };
}

function bajarMonticulo(datos, i, tamano, compara) {
  while (2 * i + 1 < tamano) {
    const izquierdo = 2 * i + 1;
    const derecho = izquierdo + 1;
    const hijo =
      derecho < tamano && compara(datos[derecho], datos[izquierdo]) < 0
        ? derecho
        : izquierdo;
    if (compara(datos[hijo], datos[i]) >= 0) return;
    [datos[i], datos[hijo]] = [datos[hijo], datos[i]];
    i = hijo;
  }
}
function construirMonticulo(datos, compara) {
  const copia = datos.slice();
  for (let i = Math.floor(copia.length / 2) - 1; i >= 0; i--)
    bajarMonticulo(copia, i, copia.length, compara);
  return copia;
}
function vistaMonticulo(numeros) {
  return construirMonticulo(numeros, (a, b) => a - b);
}

function crearColaPrioridad(datos, compara) {
  const heap = construirMonticulo(datos, compara);
  return {
    tamano: () => heap.length,
    ver: () => heap[0] ?? null,
    agregar(valor) {
      heap.push(valor);
      let i = heap.length - 1;
      while (i > 0) {
        const padre = Math.floor((i - 1) / 2);
        if (compara(heap[i], heap[padre]) >= 0) break;
        [heap[i], heap[padre]] = [heap[padre], heap[i]];
        i = padre;
      }
    },
    extraer() {
      if (!heap.length) return null;
      const primero = heap[0];
      const ultimo = heap.pop();
      if (heap.length) {
        heap[0] = ultimo;
        bajarMonticulo(heap, 0, heap.length, compara);
      }
      return primero;
    },
  };
}
function prioridadesNumericas(datos, acciones) {
  const cola = crearColaPrioridad(datos, (a, b) => a - b);
  const respuestas = [];
  for (const [accion, valor] of acciones) {
    if (accion === "agregar") cola.agregar(valor);
    else if (accion === "ver") respuestas.push(cola.ver());
    else respuestas.push(cola.extraer());
  }
  return respuestas;
}

function ordenDeAvisos(avisos) {
  const registros = avisos.map(([minuto, codigo], i) => [minuto, i, codigo]);
  const cola = crearColaPrioridad(
    registros,
    (a, b) => a[0] - b[0] || a[1] - b[1],
  );
  const orden = [];
  while (cola.tamano()) orden.push(cola.extraer()[2]);
  return orden;
}

function ordenarMonticulo(registros) {
  const compara = (a, b) => b[0] - a[0];
  const orden = construirMonticulo(registros, compara);
  for (let fin = orden.length - 1; fin > 0; fin--) {
    [orden[0], orden[fin]] = [orden[fin], orden[0]];
    bajarMonticulo(orden, 0, fin, compara);
  }
  return orden;
}

function ordenarNativo(registros) {
  return registros.toSorted((a, b) => a[0] - b[0]);
}

function contrastarEstabilidad(registros) {
  const horario = ordenarNativo(registros);
  const monticulo = ordenarMonticulo(registros);
  const mismosCodigos = horario.every(
    (registro, i) => registro[1] === monticulo[i][1],
  );
  return { horario, monticulo, mismosCodigos };
}

function porConteo(registros, maximo, clave) {
  const cuentas = Array(maximo + 1).fill(0);
  for (const registro of registros) cuentas[clave(registro)]++;
  for (let i = 1; i < cuentas.length; i++) cuentas[i] += cuentas[i - 1];
  const salida = Array(registros.length);
  for (let i = registros.length - 1; i >= 0; i--) {
    const registro = registros[i];
    const valor = clave(registro);
    cuentas[valor]--;
    salida[cuentas[valor]] = registro;
  }
  return salida;
}
function contarMinutos(registros, maximo) {
  return porConteo(registros, maximo, (registro) => registro[0]);
}

function ordenarRadix(registros) {
  let maximo = 0;
  for (const registro of registros) maximo = Math.max(maximo, registro[0]);
  let orden = registros.slice();
  for (let unidad = 1; unidad <= maximo; unidad *= 10) {
    orden = porConteo(
      orden,
      9,
      (registro) => Math.floor(registro[0] / unidad) % 10,
    );
  }
  return orden;
}

function cronologiaNumerica(registros, maximo) {
  const conteo = contarMinutos(registros, maximo);
  const radix = ordenarRadix(registros);
  const coinciden = conteo.every((registro, i) => registro[1] === radix[i][1]);
  return { conteo, radix, coinciden };
}

function seleccionarRango(datos, rango, fraccion) {
  if (rango < 0 || rango >= datos.length) return null;
  const copia = datos.slice();
  let inicio = 0;
  let fin = copia.length;
  while (inicio < fin) {
    const muestra = fraccion === undefined ? Math.random() : fraccion;
    const pivote = copia[inicio + Math.floor(muestra * (fin - inicio))];
    const [menor, mayor] = partirTres(copia, inicio, fin, pivote);
    if (rango < menor) fin = menor;
    else if (rango >= mayor) inicio = mayor;
    else return pivote;
  }
  return null;
}
function medianaHoraria(datos, fraccion) {
  if (!datos.length) return null;
  const medio = Math.floor(datos.length / 2);
  const alto = seleccionarRango(datos, medio, fraccion);
  if (datos.length % 2) return alto;
  return (seleccionarRango(datos, medio - 1, fraccion) + alto) / 2;
}

function mayoresDemoras(datos, k) {
  if (k <= 0) return [];
  const cola = crearColaPrioridad([], (a, b) => a - b);
  for (const valor of datos) {
    if (cola.tamano() < k) cola.agregar(valor);
    else if (valor > cola.ver()) {
      cola.extraer();
      cola.agregar(valor);
    }
  }
  const salida = [];
  while (cola.tamano()) salida.push(cola.extraer());
  return salida.reverse();
}

function panelDemora(datos, k, fraccion) {
  return {
    mediana: medianaHoraria(datos, fraccion),
    peores: mayoresDemoras(datos, k),
  };
}

function unificarCierres(intervalos) {
  const orden = intervalos
    .filter(([inicio, fin]) => inicio < fin)
    .toSorted((a, b) => a[0] - b[0]);
  const union = [];
  for (const [inicio, fin] of orden) {
    const anterior = union.at(-1);
    if (anterior && inicio <= anterior[1])
      anterior[1] = Math.max(anterior[1], fin);
    else union.push([inicio, fin]);
  }
  return union;
}

function barrerAndenes(intervalos) {
  const marcas = [];
  for (const [inicio, fin] of intervalos) {
    if (inicio < fin) marcas.push([inicio, 1], [fin, -1]);
  }
  marcas.sort((a, b) => a[0] - b[0]);
  const cambios = [];
  let ocupados = 0;
  let pico = 0;
  for (let i = 0; i < marcas.length;) {
    const minuto = marcas[i][0];
    while (i < marcas.length && marcas[i][0] === minuto) {
      ocupados += marcas[i][1];
      i++;
    }
    cambios.push([minuto, ocupados]);
    pico = Math.max(pico, ocupados);
  }
  return { pico, cambios };
}

function reporteDeVia(intervalos, minuto) {
  const cierres = unificarCierres(intervalos);
  const { pico } = barrerAndenes(intervalos);
  const bloqueada = cierres.some(
    ([inicio, fin]) => inicio <= minuto && minuto < fin,
  );
  return { cierres, pico, bloqueada };
}

function agendaInicial(viajes) {
  return ordenarMezcla(viajes.map(([id, origen, salida]) => [salida, id]));
}

