function ordenDeAvisos(avisos) {
  const registros = avisos.map(([minuto, codigo], i) => [minuto, i, codigo]);
  const cola = crearColaPrioridad(
    registros,
    (a, b) => a[0] - b[0] || a[1] - b[1],
  );
  const orden = [];
  while (cola.tamano()) orden.push(cola.extraer()[2]);
  return orden;
}

function ordenarMonticulo(registros) {
  const compara = (a, b) => b[0] - a[0];
  const orden = construirMonticulo(registros, compara);
  for (let fin = orden.length - 1; fin > 0; fin--) {
    [orden[0], orden[fin]] = [orden[fin], orden[0]];
    bajarMonticulo(orden, 0, fin, compara);
  }
  return orden;
}

function ordenarNativo(registros) {
  return registros.toSorted((a, b) => a[0] - b[0]);
}

function contrastarEstabilidad(registros) {
  const horario = ordenarNativo(registros);
  const monticulo = ordenarMonticulo(registros);
  const mismosCodigos = horario.every(
    (registro, i) => registro[1] === monticulo[i][1],
  );
  return { horario, monticulo, mismosCodigos };
}

function porConteo(registros, maximo, clave) {
  const cuentas = Array(maximo + 1).fill(0);
  for (const registro of registros) cuentas[clave(registro)]++;
  for (let i = 1; i < cuentas.length; i++) cuentas[i] += cuentas[i - 1];
  const salida = Array(registros.length);
  for (let i = registros.length - 1; i >= 0; i--) {
    const registro = registros[i];
    const valor = clave(registro);
    cuentas[valor]--;
    salida[cuentas[valor]] = registro;
  }
  return salida;
}
function contarMinutos(registros, maximo) {
  return porConteo(registros, maximo, (registro) => registro[0]);
}

function ordenarRadix(registros) {
  let maximo = 0;
  for (const registro of registros) maximo = Math.max(maximo, registro[0]);
  let orden = registros.slice();
  for (let unidad = 1; unidad <= maximo; unidad *= 10) {
    orden = porConteo(
      orden,
      9,
      (registro) => Math.floor(registro[0] / unidad) % 10,
    );
  }
  return orden;
}

function cronologiaNumerica(registros, maximo) {
  const conteo = contarMinutos(registros, maximo);
  const radix = ordenarRadix(registros);
  const coinciden = conteo.every((registro, i) => registro[1] === radix[i][1]);
  return { conteo, radix, coinciden };
}

function seleccionarRango(datos, rango, fraccion) {
  if (rango < 0 || rango >= datos.length) return null;
  const copia = datos.slice();
  let inicio = 0;
  let fin = copia.length;
  while (inicio < fin) {
    const muestra = fraccion === undefined ? Math.random() : fraccion;
    const pivote = copia[inicio + Math.floor(muestra * (fin - inicio))];
    const [menor, mayor] = partirTres(copia, inicio, fin, pivote);
    if (rango < menor) fin = menor;
    else if (rango >= mayor) inicio = mayor;
    else return pivote;
  }
  return null;
}
function medianaHoraria(datos, fraccion) {
  if (!datos.length) return null;
  const medio = Math.floor(datos.length / 2);
  const alto = seleccionarRango(datos, medio, fraccion);
  if (datos.length % 2) return alto;
  return (seleccionarRango(datos, medio - 1, fraccion) + alto) / 2;
}

function mayoresDemoras(datos, k) {
  if (k <= 0) return [];
  const cola = crearColaPrioridad([], (a, b) => a - b);
  for (const valor of datos) {
    if (cola.tamano() < k) cola.agregar(valor);
    else if (valor > cola.ver()) {
      cola.extraer();
      cola.agregar(valor);
    }
  }
  const salida = [];
  while (cola.tamano()) salida.push(cola.extraer());
  return salida.reverse();
}

function panelDemora(datos, k, fraccion) {
  return {
    mediana: medianaHoraria(datos, fraccion),
    peores: mayoresDemoras(datos, k),
  };
}

function unificarCierres(intervalos) {
  const orden = intervalos
    .filter(([inicio, fin]) => inicio < fin)
    .toSorted((a, b) => a[0] - b[0]);
  const union = [];
  for (const [inicio, fin] of orden) {
    const anterior = union.at(-1);
    if (anterior && inicio <= anterior[1])
      anterior[1] = Math.max(anterior[1], fin);
    else union.push([inicio, fin]);
  }
  return union;
}

function barrerAndenes(intervalos) {
  const marcas = [];
  for (const [inicio, fin] of intervalos) {
    if (inicio < fin) marcas.push([inicio, 1], [fin, -1]);
  }
  marcas.sort((a, b) => a[0] - b[0]);
  const cambios = [];
  let ocupados = 0;
  let pico = 0;
  for (let i = 0; i < marcas.length;) {
    const minuto = marcas[i][0];
    while (i < marcas.length && marcas[i][0] === minuto) {
      ocupados += marcas[i][1];
      i++;
    }
    cambios.push([minuto, ocupados]);
    pico = Math.max(pico, ocupados);
  }
  return { pico, cambios };
}

function reporteDeVia(intervalos, minuto) {
  const cierres = unificarCierres(intervalos);
  const { pico } = barrerAndenes(intervalos);
  const bloqueada = cierres.some(
    ([inicio, fin]) => inicio <= minuto && minuto < fin,
  );
  return { cierres, pico, bloqueada };
}

function agendaInicial(viajes) {
  return ordenarMezcla(viajes.map(([id, origen, salida]) => [salida, id]));
}

function simularLlegadas(viajes, hasta) {
  const eventos = viajes.map((viaje, i) => [viaje[2], i, i, 0]);
  const cola = crearColaPrioridad(
    eventos,
    (a, b) => a[0] - b[0] || a[1] - b[1],
  );
  const resultados = [];
  let alta = viajes.length;
  while (cola.tamano() && cola.ver()[0] <= hasta) {
    const [minuto, , i, parada] = cola.extraer();
    const [id, , , duraciones] = viajes[i];
    resultados.push([minuto, id, parada]);
    if (parada < duraciones.length) {
      const proximo = minuto + duraciones[parada];
      cola.agregar([proximo, alta++, i, parada + 1]);
    }
  }
  return resultados;
}

function servicioTesla(estaciones, consulta, viajes, desde, hasta) {
  const { respuestas } = catalogoTesla(estaciones, [["exacta", consulta]], 1);
  const codigos = respuestas[0].codigos;
  const origenes = new Set(codigos);
  const filtrados = viajes.filter(([, origen]) => origenes.has(origen));
  const horario = agendaInicial(filtrados);
  const posicion = limiteHorario(
    horario.map((registro) => registro[0]),
    desde,
  );
  return {
    codigos,
    horario,
    proxima: horario[posicion] ?? null,
    eventos: simularLlegadas(filtrados, hasta),
  };
}

function bajarMonticulo(datos, i, tamano, compara) {
  while (2 * i + 1 < tamano) {
    const izquierdo = 2 * i + 1;
    const derecho = izquierdo + 1;
    const hijo =
      derecho < tamano && compara(datos[derecho], datos[izquierdo]) < 0
        ? derecho
        : izquierdo;
    if (compara(datos[hijo], datos[i]) >= 0) return;
    [datos[i], datos[hijo]] = [datos[hijo], datos[i]];
    i = hijo;
  }
}
function construirMonticulo(datos, compara) {
  const copia = datos.slice();
  for (let i = Math.floor(copia.length / 2) - 1; i >= 0; i--)
    bajarMonticulo(copia, i, copia.length, compara);
  return copia;
}
function vistaMonticulo(numeros) {
  return construirMonticulo(numeros, (a, b) => a - b);
}
function crearColaPrioridad(datos, compara) {
  const heap = construirMonticulo(datos, compara);
  return {
    tamano: () => heap.length,
    ver: () => heap[0] ?? null,
    agregar(valor) {
      heap.push(valor);
      let i = heap.length - 1;
      while (i > 0) {
        const padre = Math.floor((i - 1) / 2);
        if (compara(heap[i], heap[padre]) >= 0) break;
        [heap[i], heap[padre]] = [heap[padre], heap[i]];
        i = padre;
      }
    },
    extraer() {
      if (!heap.length) return null;
      const primero = heap[0];
      const ultimo = heap.pop();
      if (heap.length) {
        heap[0] = ultimo;
        bajarMonticulo(heap, 0, heap.length, compara);
      }
      return primero;
    },
  };
}
