function entregasDePaquetes(paquetes, hasta) {
  const cola = crearColaPrioridad(
    paquetes.map(([, minuto], i) => [minuto, i, i, false]),
    (a, b) => a[0] - b[0] || a[1] - b[1],
  );
  let alta = paquetes.length;
  const entregadas = [];
  while (cola.tamano() && cola.ver()[0] <= hasta) {
    const [minuto, , i, fin] = cola.extraer();
    if (fin) entregadas.push([minuto, paquetes[i][0]]);
    else cola.agregar([minuto + paquetes[i][2], alta++, i, true]);
  }
  return entregadas;
}
